const iframe=document.getElementById("form-embed"),wrapper=iframe.closest(".iframe-wrapper"),loaderText=wrapper.querySelector(".loader-text");iframe.style.opacity=0;let textTimeout=setTimeout((()=>{loaderText.classList.add("visible")}),100);function loadFormEmbed(){const e=document.createElement("script");e.src="https://forms.arion2000.xyz/widgets/iframe.min.js",e.onload=()=>{initEmbed("form-embed",{autoResize:!0})},document.body.appendChild(e)}iframe.addEventListener("load",(()=>{clearTimeout(textTimeout),loaderText.classList.remove("visible"),setTimeout((()=>{wrapper.querySelector(".loader-bar").style.display="none",iframe.style.opacity=1}),300)})),document.addEventListener("DOMContentLoaded",loadFormEmbed);
